begin;
create temp table qa_ids(k text primary key,v uuid);
insert into qa_ids values ('admin',gen_random_uuid()),('member',gen_random_uuid()),('outsider',gen_random_uuid()),('template',gen_random_uuid()),('client',gen_random_uuid()),('assessment',gen_random_uuid());
grant select on qa_ids to authenticated,anon;
insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data) select v,k||'-grant-qa@example.invalid',now(),'{}' from qa_ids where k in ('admin','member','outsider');
insert into public.user_roles(user_id,role) select v,(case when k='admin' then 'admin' else 'socio' end)::public.app_role from qa_ids where k in ('admin','member');
create temp table qa_pass(name text);
grant insert,select on qa_pass to authenticated,anon;
create function pg_temp.assert_true(ok boolean,label text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'FAIL: %',label; end if; insert into qa_pass values(label); end $$;
create function pg_temp.expect_denied(statement text,label text) returns void language plpgsql as $$ declare rejected boolean:=false; begin begin execute statement; exception when others then rejected:=true; end; perform pg_temp.assert_true(rejected,label); end $$;
set local role authenticated;
select set_config('request.jwt.claim.sub',(select v::text from qa_ids where k='admin'),true);
insert into public.grant_templates(id,scheme_key,version,definition,review) select (select v from qa_ids where k='template'),'bando_sintetico',1,$d${"schemaVersion":1,"id":"bando_sintetico","version":1,"title":"Bando sintetico di collaudo","description":"Dati inventati esclusivamente per i test.","sources":[{"id":"avviso","name":"avviso-sintetico.pdf","sha256":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","pages":[{"page":1,"text":"Sono ammesse imprese attive con almeno 14.000 euro di investimento. Contributo 50% fino a 10.000 euro. Certificazione: 5 punti. Escluse procedure concorsuali."}]}],"questions":[{"id":"attiva","section":"Requisiti","label":"Impresa attiva?","type":"boolean","required":true,"citations":[{"documentId":"avviso","page":1,"quote":"Sono ammesse imprese attive con almeno 14.000 euro di investimento. Contributo 50% fino a 10.000 euro. Certificazione: 5 punti. Escluse procedure concorsuali."}]},{"id":"procedura","section":"Requisiti","label":"Procedura concorsuale?","type":"boolean","required":true,"citations":[{"documentId":"avviso","page":1,"quote":"Sono ammesse imprese attive con almeno 14.000 euro di investimento. Contributo 50% fino a 10.000 euro. Certificazione: 5 punti. Escluse procedure concorsuali."}]},{"id":"investimento","section":"Progetto","label":"Investimento","type":"number","min":0,"required":true,"citations":[{"documentId":"avviso","page":1,"quote":"Sono ammesse imprese attive con almeno 14.000 euro di investimento. Contributo 50% fino a 10.000 euro. Certificazione: 5 punti. Escluse procedure concorsuali."}]},{"id":"certificata","section":"Punteggio","label":"Certificata?","type":"boolean","required":true,"citations":[{"documentId":"avviso","page":1,"quote":"Sono ammesse imprese attive con almeno 14.000 euro di investimento. Contributo 50% fino a 10.000 euro. Certificazione: 5 punti. Escluse procedure concorsuali."}]}],"rules":[{"id":"impresa_attiva","label":"Impresa attiva","kind":"eligibility","condition":{"op":"eq","field":"attiva","value":true},"citations":[{"documentId":"avviso","page":1,"quote":"Sono ammesse imprese attive con almeno 14.000 euro di investimento. Contributo 50% fino a 10.000 euro. Certificazione: 5 punti. Escluse procedure concorsuali."}]},{"id":"esclusione_procedura","label":"Procedura concorsuale","kind":"exclusion","condition":{"op":"eq","field":"procedura","value":true},"citations":[{"documentId":"avviso","page":1,"quote":"Sono ammesse imprese attive con almeno 14.000 euro di investimento. Contributo 50% fino a 10.000 euro. Certificazione: 5 punti. Escluse procedure concorsuali."}]},{"id":"soglia","label":"Investimento minimo","kind":"eligibility","condition":{"op":"gte","field":"investimento","value":14000},"citations":[{"documentId":"avviso","page":1,"quote":"Sono ammesse imprese attive con almeno 14.000 euro di investimento. Contributo 50% fino a 10.000 euro. Certificazione: 5 punti. Escluse procedure concorsuali."}]},{"id":"contributo","label":"Contributo","kind":"grant","formula":{"op":"min","args":[{"op":"constant","value":10000},{"op":"multiply","args":[{"op":"field","field":"investimento"},{"op":"constant","value":0.5}]}]},"maximum":10000,"citations":[{"documentId":"avviso","page":1,"quote":"Sono ammesse imprese attive con almeno 14.000 euro di investimento. Contributo 50% fino a 10.000 euro. Certificazione: 5 punti. Escluse procedure concorsuali."}]},{"id":"punti","label":"Certificazione","kind":"score","formula":{"op":"if","when":{"op":"eq","field":"certificata","value":true},"then":{"op":"constant","value":5},"otherwise":{"op":"constant","value":0}},"maximum":5,"citations":[{"documentId":"avviso","page":1,"quote":"Sono ammesse imprese attive con almeno 14.000 euro di investimento. Contributo 50% fino a 10.000 euro. Certificazione: 5 punti. Escluse procedure concorsuali."}]}],"unresolved":[]}$d$::jsonb,$r${"sources":["avviso:1"],"items":["question:attiva","question:procedura","question:investimento","question:certificata","rule:impresa_attiva","rule:esclusione_procedura","rule:soglia","rule:contributo","rule:punti"],"scenarios":[{"name":"Soglia esatta","answers":{"attiva":true,"procedura":false,"investimento":14000,"certificata":false},"expected":"pre_eligible","score":0,"grants":{"contributo":7000}},{"name":"Sotto soglia","answers":{"attiva":true,"procedura":false,"investimento":13999.99,"certificata":false},"expected":"not_eligible","score":0,"grants":{"contributo":7000}},{"name":"Informazioni mancanti","answers":{},"expected":"incomplete","score":null,"grants":{"contributo":null}}]}$r$::jsonb;
select pg_temp.assert_true((select count(*)=1 from public.grant_templates where id=(select v from qa_ids where k='template')),'admin reads draft');
select pg_temp.expect_denied($q$insert into public.grant_templates(scheme_key,version,definition) values('broken',1,'{}')$q$,'malformed definition rejected');
select set_config('request.jwt.claim.sub',(select v::text from qa_ids where k='member'),true);
select pg_temp.assert_true((select count(*)=0 from public.grant_templates where id=(select v from qa_ids where k='template')),'member cannot read draft');
select pg_temp.expect_denied($q$insert into public.grant_templates(scheme_key,version,definition) select 'bando_sintetico',1,$d${"schemaVersion":1,"id":"bando_sintetico","version":1,"title":"Bando sintetico di collaudo","description":"Dati inventati esclusivamente per i test.","sources":[{"id":"avviso","name":"avviso-sintetico.pdf","sha256":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","pages":[{"page":1,"text":"Sono ammesse imprese attive con almeno 14.000 euro di investimento. Contributo 50% fino a 10.000 euro. Certificazione: 5 punti. Escluse procedure concorsuali."}]}],"questions":[{"id":"attiva","section":"Requisiti","label":"Impresa attiva?","type":"boolean","required":true,"citations":[{"documentId":"avviso","page":1,"quote":"Sono ammesse imprese attive con almeno 14.000 euro di investimento. Contributo 50% fino a 10.000 euro. Certificazione: 5 punti. Escluse procedure concorsuali."}]},{"id":"procedura","section":"Requisiti","label":"Procedura concorsuale?","type":"boolean","required":true,"citations":[{"documentId":"avviso","page":1,"quote":"Sono ammesse imprese attive con almeno 14.000 euro di investimento. Contributo 50% fino a 10.000 euro. Certificazione: 5 punti. Escluse procedure concorsuali."}]},{"id":"investimento","section":"Progetto","label":"Investimento","type":"number","min":0,"required":true,"citations":[{"documentId":"avviso","page":1,"quote":"Sono ammesse imprese attive con almeno 14.000 euro di investimento. Contributo 50% fino a 10.000 euro. Certificazione: 5 punti. Escluse procedure concorsuali."}]},{"id":"certificata","section":"Punteggio","label":"Certificata?","type":"boolean","required":true,"citations":[{"documentId":"avviso","page":1,"quote":"Sono ammesse imprese attive con almeno 14.000 euro di investimento. Contributo 50% fino a 10.000 euro. Certificazione: 5 punti. Escluse procedure concorsuali."}]}],"rules":[{"id":"impresa_attiva","label":"Impresa attiva","kind":"eligibility","condition":{"op":"eq","field":"attiva","value":true},"citations":[{"documentId":"avviso","page":1,"quote":"Sono ammesse imprese attive con almeno 14.000 euro di investimento. Contributo 50% fino a 10.000 euro. Certificazione: 5 punti. Escluse procedure concorsuali."}]},{"id":"esclusione_procedura","label":"Procedura concorsuale","kind":"exclusion","condition":{"op":"eq","field":"procedura","value":true},"citations":[{"documentId":"avviso","page":1,"quote":"Sono ammesse imprese attive con almeno 14.000 euro di investimento. Contributo 50% fino a 10.000 euro. Certificazione: 5 punti. Escluse procedure concorsuali."}]},{"id":"soglia","label":"Investimento minimo","kind":"eligibility","condition":{"op":"gte","field":"investimento","value":14000},"citations":[{"documentId":"avviso","page":1,"quote":"Sono ammesse imprese attive con almeno 14.000 euro di investimento. Contributo 50% fino a 10.000 euro. Certificazione: 5 punti. Escluse procedure concorsuali."}]},{"id":"contributo","label":"Contributo","kind":"grant","formula":{"op":"min","args":[{"op":"constant","value":10000},{"op":"multiply","args":[{"op":"field","field":"investimento"},{"op":"constant","value":0.5}]}]},"maximum":10000,"citations":[{"documentId":"avviso","page":1,"quote":"Sono ammesse imprese attive con almeno 14.000 euro di investimento. Contributo 50% fino a 10.000 euro. Certificazione: 5 punti. Escluse procedure concorsuali."}]},{"id":"punti","label":"Certificazione","kind":"score","formula":{"op":"if","when":{"op":"eq","field":"certificata","value":true},"then":{"op":"constant","value":5},"otherwise":{"op":"constant","value":0}},"maximum":5,"citations":[{"documentId":"avviso","page":1,"quote":"Sono ammesse imprese attive con almeno 14.000 euro di investimento. Contributo 50% fino a 10.000 euro. Certificazione: 5 punti. Escluse procedure concorsuali."}]}],"unresolved":[]}$d$::jsonb$q$,'member cannot create templates');
select set_config('request.jwt.claim.sub',(select v::text from qa_ids where k='admin'),true);
-- Inventory checks execute as the authenticated admin, not a privileged role.
update public.grant_templates set definition=jsonb_set(definition,'{requirements}',jsonb_build_array(jsonb_build_object('id','req_active','label','Requisito sintetico','citations',definition->'questions'->0->'citations','questionIds','["attiva"]'::jsonb,'ruleIds','["impresa_attiva"]'::jsonb,'gap','Da verificare'))) where id=(select v from qa_ids where k='template');
select pg_temp.expect_denied($q$update public.grant_templates set published_at=now() where id=(select v from qa_ids where k='template')$q$,'inventory gap blocks publication');
update public.grant_templates set definition=definition#-'{requirements,0,gap}' where id=(select v from qa_ids where k='template');
select pg_temp.expect_denied($q$update public.grant_templates set published_at=now() where id=(select v from qa_ids where k='template')$q$,'unreviewed inventory blocks publication');
update public.grant_templates set review=jsonb_set(review,'{items}',review->'items'||'["requirement:req_active"]'::jsonb), definition=jsonb_set(definition,'{requirements,0,ruleIds}','["missing_rule"]') where id=(select v from qa_ids where k='template');
select pg_temp.expect_denied($q$update public.grant_templates set published_at=now() where id=(select v from qa_ids where k='template')$q$,'nonexistent inventory rule blocks publication');
update public.grant_templates set definition=jsonb_set(definition,'{requirements,0,ruleIds}','[]') where id=(select v from qa_ids where k='template');
select pg_temp.expect_denied($q$update public.grant_templates set published_at=now() where id=(select v from qa_ids where k='template')$q$,'empty inventory coverage blocks publication');
update public.grant_templates set definition=jsonb_set(definition,'{requirements,0,ruleIds}','["impresa_attiva"]') where id=(select v from qa_ids where k='template');
update public.grant_templates set published_at=now() where id=(select v from qa_ids where k='template');
select pg_temp.assert_true((select revision=7 and published_at is not null from public.grant_templates where id=(select v from qa_ids where k='template')),'admin publishes reviewed version');
with changed as (update public.grant_templates set definition=jsonb_set(definition,'{title}','"Changed"') where id=(select v from qa_ids where k='template') returning id) select pg_temp.assert_true((select count(*)=0 from changed),'published version cannot be modified');
with removed as (delete from public.grant_templates where id=(select v from qa_ids where k='template') returning id) select pg_temp.assert_true((select count(*)=0 from removed),'published version cannot be deleted');
select pg_temp.assert_true((select count(*)=1 from public.grant_templates where id=(select v from qa_ids where k='template')),'published version still present');
select set_config('request.jwt.claim.sub',(select v::text from qa_ids where k='member'),true);
select pg_temp.assert_true((select count(*)=1 from public.grant_templates where id=(select v from qa_ids where k='template')),'member reads published version');
insert into public.clients(id,ragione_sociale,created_by) select (select v from qa_ids where k='client'),'Azienda sintetica QA',(select v from qa_ids where k='member');
insert into public.assessments(id,client_id,title,created_by,answers) select (select v from qa_ids where k='assessment'),(select v from qa_ids where k='client'),'Assessment sintetico QA',(select v from qa_ids where k='member'),jsonb_build_object('_assessment_type','configurable_grant_v1','_grant_version_id',(select v::text from qa_ids where k='template'),'_grant_answers','{}'::jsonb);
select pg_temp.assert_true((select count(*)=1 from public.assessments where id=(select v from qa_ids where k='assessment')),'member saves assessment with published version');
select pg_temp.expect_denied($q$update public.assessments set answers='{}' where id=(select v from qa_ids where k='assessment')$q$,'cannot overwrite version through another editor');
select set_config('request.jwt.claim.sub',(select v::text from qa_ids where k='outsider'),true);
select pg_temp.assert_true((select count(*)=0 from public.grant_templates where id=(select v from qa_ids where k='template')),'outsider cannot read published templates');
select pg_temp.assert_true((select count(*)=0 from public.assessments where id=(select v from qa_ids where k='assessment')),'outsider cannot read assessment');
set local role anon;
select pg_temp.expect_denied($q$select * from public.grant_templates$q$,'anonymous cannot read templates');
reset role;
select * from qa_pass;
rollback;
